import os
import json
from collections import defaultdict, Counter

# === Configuration ===
root_dir = "" #Directory to XAnyLabeling Directory

# Define which keypoints are valid for each object class
required_keypoints = {
    "chicken": {"left-eye", "right-eye", "head", "left-wing", "right-wing", "left-foot", "right-foot", "tail", "center"},
    "feeder": {"top-center"},
    "drinker": {"top-center"}
}
object_classes = required_keypoints.keys()

def analyze_json(path):
    issues = []
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        return [f"❌ Could not read JSON: {e}"]

    shapes = data.get("shapes", [])
    if not shapes:
        return ["❌ No shapes found in file"]

    groups = defaultdict(list)
    shape_hashes = set()

    for shape in shapes:
        label = shape.get("label")
        group_id = shape.get("group_id")
        shape_type = shape.get("shape_type")
        points = shape.get("points")

        # Check for missing group_id
        if group_id is None:
            issues.append(f"⚠️ Shape with label '{label}' is missing group_id")

        # Check for missing or malformed label
        if not isinstance(label, str):
            issues.append("⚠️ Shape is missing a valid 'label' field")

        # Check for missing or malformed points
        if not isinstance(points, list) or not points:
            issues.append(f"⚠️ Shape with label '{label}' has invalid or missing 'points'")

        # Check for duplicate shapes
        shape_sig = (group_id, label, tuple(map(tuple, points or [])))
        if shape_sig in shape_hashes:
            issues.append(f"⚠️ Duplicate shape detected: label={label}, group={group_id}")
        shape_hashes.add(shape_sig)

        # Group shapes by group_id
        if group_id is not None:
            groups[group_id].append(shape)

    # Validate each group
    for gid, group_shapes in groups.items():
        labels = {s["label"] for s in group_shapes}
        rects = [s for s in group_shapes if s["shape_type"] == "rectangle"]
        obj_class = next((l for l in labels if l in object_classes), None)

        if not obj_class:
            issues.append(f"⚠️ Group {gid} has no object class label (e.g. chicken/feeder/drinker)")

        if len(rects) == 0:
            issues.append(f"❌ Group {gid} has no bounding box")
        elif len(rects) > 1:
            issues.append(f"❌ Group {gid} has multiple bounding boxes")
        else:
            rect_label = rects[0]["label"]
            if obj_class and rect_label != obj_class:
                issues.append(f"❌ Group {gid} bounding box label '{rect_label}' doesn't match object class '{obj_class}'")

        # Keypoint visibility check
        if obj_class:
            has_keypoints = any(
                s["label"] in required_keypoints[obj_class] and s.get("points")
                for s in group_shapes
            )
            if not has_keypoints:
                issues.append(f"❌ Group {gid} has no visible keypoints for class '{obj_class}'")

    return issues


# === Run the validator ===
print("🔍 Scanning for annotation issues...\n")
any_issues = False
for root, _, files in os.walk(root_dir):
    for file in files:
        if file.endswith(".json"):
            path = os.path.join(root, file)
            problems = analyze_json(path)
            if problems:
                any_issues = True
                print(f"\n❌ Issues found in file: {file}")
                for issue in problems:
                    print(f"   {issue}")

if not any_issues:
    print("✅ All JSON files are clean!")

# stabilization_comparison_strict.py
"""
Comprehensive video stabilization comparison script (strict: no automatic fallback)
Compares: FFmpeg vid.stab, VidGear Stab, MediaPipe, and python_video_stab
This variant WILL NOT silently use the OpenCV fallback if mediapipe or vidgear are missing.
Instead it reports a clear error telling you how to install the missing dependency.
"""

import os
import cv2
import numpy as np
import subprocess
import json
import time
from pathlib import Path
import matplotlib.pyplot as plt
from tqdm import tqdm
import importlib.util

class VideoStabilizationComparator:
    def __init__(self, output_dir="stabilization_comparison"):
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(exist_ok=True)

        # keep references to imported modules (if available)
        self.modules = {}

        # Initialize stabilization methods
        self.stabilizers = {}
        self.setup_stabilizers()

        # Metrics storage
        self.results = {}

    def is_module_available(self, module_name):
        """Check if a module is importable without importing it"""
        return importlib.util.find_spec(module_name) is not None

    def setup_stabilizers(self):
        """Initialize all available stabilization methods and verify imports"""
        # python_video_stab availability
        self.stabilizers['python_video_stab'] = {
            'function': self.stabilize_python_video_stab,
            'available': self.is_module_available('vidstab')
        }
        if self.stabilizers['python_video_stab']['available']:
            self.modules['vidstab'] = True

        # mediapipe availability
        mediapipe_available = self.is_module_available('mediapipe')
        self.stabilizers['mediapipe'] = {
            'function': self.stabilize_mediapipe,
            'available': mediapipe_available
        }
        if mediapipe_available:
            self.modules['mediapipe'] = True

        # FFmpeg vidstab check (external program)
        self.stabilizers['ffmpeg_vidstab'] = {
            'function': self.stabilize_ffmpeg_vidstab,
            'available': self.check_ffmpeg_available()
        }

        # vidgear availability
        vidgear_available = self.is_module_available('vidgear')
        self.stabilizers['vidgear'] = {
            'function': self.stabilize_vidgear,
            'available': vidgear_available
        }
        if vidgear_available:
            self.modules['vidgear'] = True

    def check_ffmpeg_available(self):
        """Check if FFmpeg is available in system path"""
        try:
            result = subprocess.run(['ffmpeg', '-version'], capture_output=True, text=True)
            return result.returncode == 0
        except:
            return False

    # -------------------------
    # Jitter / utility methods (unchanged)
    # -------------------------
    def add_artificial_jitter(self, video_path, output_path, jitter_type="mixed"):
        cap = cv2.VideoCapture(str(video_path))
        fps = cap.get(cv2.CAP_PROP_FPS)
        width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        fourcc = cv2.VideoWriter_fourcc(*'mp4v')
        out = cv2.VideoWriter(str(output_path), fourcc, fps, (width, height))
        print(f"Adding {jitter_type} jitter to video...")
        frame_count = 0
        jitter_params = {'translation_x': 0, 'translation_y': 0, 'rotation': 0, 'scale': 1.0}
        while True:
            ret, frame = cap.read()
            if not ret:
                break
            jittered_frame = self.apply_jitter(frame, jitter_params, jitter_type, frame_count)
            out.write(jittered_frame)
            frame_count += 1
            self.update_jitter_params(jitter_params, jitter_type, frame_count)
        cap.release()
        out.release()
        print(f"Jittery video saved to: {output_path}")

    def apply_jitter(self, frame, params, jitter_type, frame_count):
        h, w = frame.shape[:2]
        center = (w // 2, h // 2)
        M = np.float32([[1, 0, params['translation_x']], [0, 1, params['translation_y']]])
        jittered = cv2.warpAffine(frame, M, (w, h))
        if abs(params['rotation']) > 0.1 or abs(params['scale'] - 1.0) > 0.01:
            rotation_matrix = cv2.getRotationMatrix2D(center, params['rotation'], params['scale'])
            jittered = cv2.warpAffine(jittered, rotation_matrix, (w, h))
        return jittered

    def update_jitter_params(self, params, jitter_type, frame_count):
        if jitter_type == "shake":
            params['translation_x'] = np.random.randint(-15, 15)
            params['translation_y'] = np.random.randint(-15, 15)
            params['rotation'] = np.random.uniform(-2, 2)
            params['scale'] = 1.0
        elif jitter_type == "drift":
            drift_freq = 0.1
            params['translation_x'] = 20 * np.sin(frame_count * drift_freq)
            params['translation_y'] = 15 * np.cos(frame_count * drift_freq * 0.7)
            params['rotation'] = 1 * np.sin(frame_count * drift_freq * 0.5)
            params['scale'] = 1.0
        elif jitter_type == "zoom":
            zoom_freq = 0.05
            zoom_amount = 0.2 * np.sin(frame_count * zoom_freq)
            params['scale'] = 1.0 + zoom_amount
            params['translation_x'] = 0
            params['translation_y'] = 0
            params['rotation'] = 0
        elif jitter_type == "mixed":
            if frame_count % 30 < 10:
                params['translation_x'] = np.random.randint(-10, 10)
                params['translation_y'] = np.random.randint(-10, 10)
                params['scale'] = 1.0
            elif frame_count % 30 < 20:
                drift_freq = 0.08
                params['translation_x'] = 15 * np.sin(frame_count * drift_freq)
                params['translation_y'] = 10 * np.cos(frame_count * drift_freq * 0.8)
                params['scale'] = 1.0
            else:
                zoom_freq = 0.03
                zoom_amount = 0.15 * np.sin(frame_count * zoom_freq)
                params['scale'] = 1.0 + zoom_amount
                params['translation_x'] = 0
                params['translation_y'] = 0
            params['rotation'] = 0.5 * np.sin(frame_count * 0.1)

    # -------------------------
    # Stabilizers (strict: no fallback)
    # -------------------------
    def stabilize_ffmpeg_vidstab(self, input_path, output_path):
        print("Stabilizing with FFmpeg vid.stab...")
        temp_trf = self.output_dir / "transforms.trf"
        cmd1 = [
            'ffmpeg', '-i', str(input_path), '-vf', 'vidstabdetect=shakiness=5:accuracy=15:result=' + str(temp_trf),
            '-f', 'null', '-'
        ]
        cmd2 = [
            'ffmpeg', '-i', str(input_path), '-vf',
            f'vidstabtransform=smoothing=10:input={temp_trf},unsharp=5:5:0.8:3:3:0.4',
            '-c:a', 'copy', str(output_path), '-y'
        ]
        try:
            result1 = subprocess.run(cmd1, capture_output=True, text=True)
            if result1.returncode != 0:
                return {'success': False, 'error': f"FFmpeg analysis failed: {result1.stderr}"}
            start_time = time.time()
            result2 = subprocess.run(cmd2, capture_output=True, text=True)
            processing_time = time.time() - start_time
            if temp_trf.exists():
                temp_trf.unlink()
            if result2.returncode == 0:
                return {'success': True, 'processing_time': processing_time, 'used_path': 'ffmpeg_vidstab'}
            else:
                return {'success': False, 'error': f"FFmpeg stabilization failed: {result2.stderr}"}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def stabilize_vidgear(self, input_path, output_path):
        """Stabilize using VidGear Stabilizer class (correct import)."""
        print("Stabilizing with VidGear (Stabilizer)...")
        if not self.stabilizers['vidgear']['available']:
            return {'success': False,
                    'error': ("VidGear not installed or not importable. Install with: pip install vidgear"),
                    'used_path': 'vidgear_missing'}
        try:
            # correct import location and class name
            from vidgear.gears.stabilizer import Stabilizer
        except Exception as e:
            return {'success': False, 'error': f"VidGear import error: {e}", 'used_path': 'vidgear_import_error'}

        try:
            start_time = time.time()
            stab = Stabilizer()
            cap = cv2.VideoCapture(str(input_path))
            fourcc = cv2.VideoWriter_fourcc(*'mp4v')
            fps = cap.get(cv2.CAP_PROP_FPS) or 30.0
            width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
            height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
            out = cv2.VideoWriter(str(output_path), fourcc, fps, (width, height))

            frame_count = 0
            while True:
                ret, frame = cap.read()
                if not ret:
                    break
                stabilized_frame = stab.stabilize(frame)
                if stabilized_frame is not None:
                    out.write(stabilized_frame)
                else:
                    out.write(frame)
                frame_count += 1
                if frame_count % 200 == 0:
                    print(f"Processed {frame_count} frames with VidGear...")
            processing_time = time.time() - start_time
            cap.release()
            out.release()
            try:
                stab.clean()
            except Exception:
                pass
            return {'success': True, 'processing_time': processing_time, 'used_path': 'vidgear_stabilizer'}
        except Exception as e:
            return {'success': False, 'error': str(e), 'used_path': 'vidgear_exception'}


    def stabilize_mediapipe(self, input_path, output_path, landmark_source='pose'):
        """
        Use MediaPipe Pose (or FaceMesh) landmarks to estimate motion and stabilize.
        landmark_source: 'pose' (default) or 'face'
        """
        print("Stabilizing with MediaPipe landmarks...")
        if not self.stabilizers['mediapipe']['available']:
            return {'success': False,
                    'error': ("MediaPipe not installed. Install with: pip install mediapipe"),
                    'used_path': 'mediapipe_missing'}
        try:
            import mediapipe as mp
        except Exception as e:
            return {'success': False, 'error': f"Failed to import mediapipe: {e}", 'used_path': 'mediapipe_import_error'}

        # choose solution
        if landmark_source == 'pose':
            mp_sol = mp.solutions.pose
            model = mp_sol.Pose(static_image_mode=False, min_detection_confidence=0.5, min_tracking_confidence=0.5)
            landmark_indices = None  # we'll use all pose landmarks present
        else:
            mp_sol = mp.solutions.face_mesh
            model = mp_sol.FaceMesh(static_image_mode=False, max_num_faces=1,
                                    min_detection_confidence=0.5, min_tracking_confidence=0.5)

        cap = cv2.VideoCapture(str(input_path))
        fourcc = cv2.VideoWriter_fourcc(*'mp4v')
        fps = cap.get(cv2.CAP_PROP_FPS) or 30.0
        width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        out = cv2.VideoWriter(str(output_path), fourcc, fps, (width, height))

        prev_pts = None
        transforms = []
        frame_count = 0
        start_time = time.time()

        while True:
            ret, frame = cap.read()
            if not ret:
                break
            img_rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
            results = model.process(img_rgb)

            curr_pts = []
            if results:
                if landmark_source == 'pose' and results.pose_landmarks:
                    for lm in results.pose_landmarks.landmark:
                        # use x,y normalized coords -> pixel coords
                        curr_pts.append([lm.x * width, lm.y * height])
                elif landmark_source == 'face' and results.multi_face_landmarks:
                    # use first face's subset of landmarks for robustness (e.g., use outer face contour indices)
                    for lm in results.multi_face_landmarks[0].landmark:
                        curr_pts.append([lm.x * width, lm.y * height])

            curr_pts = np.array(curr_pts, dtype=np.float32) if curr_pts else None

            if prev_pts is not None and curr_pts is not None and len(prev_pts) >= 4 and len(curr_pts) >= 4:
                # find matching subset: here we assume ordering is consistent (MediaPipe preserves landmark index)
                # If ordering isn't consistent across frames, you should match points by proximity.
                # We'll pick the first min(n_prev, n_curr) to create correspondence
                n = min(len(prev_pts), len(curr_pts))
                prev_sub = prev_pts[:n]
                curr_sub = curr_pts[:n]

                m, inliers = cv2.estimateAffinePartial2D(prev_sub, curr_sub, method=cv2.RANSAC, ransacReprojThreshold=5.0)
                if m is not None:
                    transforms.append(m)
                    if len(transforms) > 15:
                        transforms.pop(0)
                    avg_m = np.mean(transforms, axis=0)
                    stabilized = cv2.warpAffine(frame, avg_m, (width, height))

                    # optional: crop black borders or fill with blurred content — here we write as-is
                    out.write(stabilized)
                else:
                    out.write(frame)
            else:
                out.write(frame)

            prev_pts = curr_pts.copy() if curr_pts is not None else None
            frame_count += 1
            if frame_count % 200 == 0:
                print(f"Processed {frame_count} frames with MediaPipe landmark stabilizer...")

        processing_time = time.time() - start_time
        cap.release()
        out.release()
        try:
            model.close()
        except Exception:
            pass

        return {'success': True, 'processing_time': processing_time, 'used_path': f'mediapipe_landmark_{landmark_source}'}


    def stabilize_python_video_stab(self, input_path, output_path):
        print("Stabilizing with python_video_stab...")
        if not self.stabilizers['python_video_stab']['available']:
            return {'success': False,
                    'error': ("python_video_stab (vidstab) not installed. Install it with: pip install vidstab"),
                    'used_path': 'vidstab_missing'}
        try:
            from vidstab import VidStab
        except Exception as e:
            return {'success': False, 'error': f"Failed to import vidstab: {e}", 'used_path': 'vidstab_import_error'}
        start_time = time.time()
        stabilizer = VidStab()
        stabilizer.stabilize(input_path=str(input_path),
                             output_path=str(output_path),
                             smoothing_window=30)
        processing_time = time.time() - start_time
        return {'success': True, 'processing_time': processing_time, 'used_path': 'python_video_stab'}

    # -------------------------
    # (unchanged) OpenCV fallback — kept for reference but NOT used automatically
    # -------------------------
    def stabilize_opencv_fallback(self, input_path, output_path, method_name):
        """OpenCV fallback (kept for reference; the strict script does not call this silently)"""
        print(f"Using OpenCV fallback stabilization for {method_name}...")
        start_time = time.time()
        cap = cv2.VideoCapture(str(input_path))
        fourcc = cv2.VideoWriter_fourcc(*'mp4v')
        fps = cap.get(cv2.CAP_PROP_FPS)
        width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        out = cv2.VideoWriter(str(output_path), fourcc, fps, (width, height))
        prev_gray = None
        transforms = []
        frame_count = 0
        while True:
            ret, frame = cap.read()
            if not ret:
                break
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            if prev_gray is not None:
                prev_pts = cv2.goodFeaturesToTrack(prev_gray, maxCorners=200, qualityLevel=0.01, minDistance=30, blockSize=3)
                if prev_pts is not None:
                    curr_pts, status, err = cv2.calcOpticalFlowPyrLK(prev_gray, gray, prev_pts, None)
                    if curr_pts is not None:
                        idx = np.where(status==1)[0]
                        prev_pts = prev_pts[idx]
                        curr_pts = curr_pts[idx]
                        if len(prev_pts) >= 4:
                            m, inliers = cv2.estimateAffinePartial2D(prev_pts, curr_pts)
                            if m is not None:
                                transforms.append(m)
                                if len(transforms) > 10:
                                    transforms.pop(0)
                                avg_m = np.mean(transforms, axis=0)
                                stabilized = cv2.warpAffine(frame, avg_m, (width, height))
                                out.write(stabilized)
                            else:
                                out.write(frame)
                        else:
                            out.write(frame)
                    else:
                        out.write(frame)
                else:
                    out.write(frame)
            else:
                out.write(frame)
                prev_gray = gray.copy()
            prev_gray = gray.copy()
            frame_count += 1
        processing_time = time.time() - start_time
        cap.release()
        out.release()
        return {'success': True, 'processing_time': processing_time, 'used_path': 'opencv_fallback'}

    # -------------------------
    # Metrics & reporting (unchanged, but ensure used_path included in results)
    # -------------------------
    def calculate_optical_flow(self, prev_frame, curr_frame):
        prev_gray = cv2.cvtColor(prev_frame, cv2.COLOR_BGR2GRAY)
        curr_gray = cv2.cvtColor(curr_frame, cv2.COLOR_BGR2GRAY)
        flow = cv2.calcOpticalFlowFarneback(prev_gray, curr_gray, None,
                                            0.5, 3, 15, 3, 5, 1.2, 0)
        return flow

    def calculate_psnr(self, img1, img2):
        try:
            mse = np.mean((img1.astype(float) - img2.astype(float)) ** 2)
            if mse == 0:
                return float('inf')
            return float(20 * np.log10(255.0 / np.sqrt(mse)))
        except:
            return 20.0

    def calculate_ssim(self, img1, img2):
        try:
            from skimage.metrics import structural_similarity as ssim_func
            gray1 = cv2.cvtColor(img1, cv2.COLOR_BGR2GRAY)
            gray2 = cv2.cvtColor(img2, cv2.COLOR_BGR2GRAY)
            return float(ssim_func(gray1, gray2))
        except ImportError:
            try:
                gray1 = cv2.cvtColor(img1, cv2.COLOR_BGR2GRAY)
                gray2 = cv2.cvtColor(img2, cv2.COLOR_BGR2GRAY)
                C1 = (0.01 * 255) ** 2
                C2 = (0.03 * 255) ** 2
                mu1 = cv2.GaussianBlur(gray1, (11, 11), 1.5)
                mu2 = cv2.GaussianBlur(gray2, (11, 11), 1.5)
                mu1_sq = mu1 ** 2
                mu2_sq = mu2 ** 2
                mu1_mu2 = mu1 * mu2
                sigma1_sq = cv2.GaussianBlur(gray1 ** 2, (11, 11), 1.5) - mu1_sq
                sigma2_sq = cv2.GaussianBlur(gray2 ** 2, (11, 11), 1.5) - mu2_sq
                sigma12 = cv2.GaussianBlur(gray1 * gray2, (11, 11), 1.5) - mu1_mu2
                ssim_map = ((2 * mu1_mu2 + C1) * (2 * sigma12 + C2)) / ((mu1_sq + mu2_sq + C1) * (sigma1_sq + sigma2_sq + C2))
                return float(np.mean(ssim_map))
            except:
                return 0.5

    def calculate_stabilization_metrics(self, original_path, stabilized_path, jittery_path):
        print("Calculating stabilization metrics...")
        cap_orig = cv2.VideoCapture(str(original_path))
        cap_stab = cv2.VideoCapture(str(stabilized_path))
        cap_jitter = cv2.VideoCapture(str(jittery_path))
        metrics = {'frame_stability': [], 'motion_reduction': [], 'psnr_values': [], 'ssim_values': []}
        frame_count = 0
        prev_frame_stab = None
        prev_frame_jitter = None
        total_frames = min(int(cap_orig.get(cv2.CAP_PROP_FRAME_COUNT)),
                           int(cap_stab.get(cv2.CAP_PROP_FRAME_COUNT)),
                           int(cap_jitter.get(cv2.CAP_PROP_FRAME_COUNT)))
        for i in range(total_frames):
            ret_orig, frame_orig = cap_orig.read()
            ret_stab, frame_stab = cap_stab.read()
            ret_jitter, frame_jitter = cap_jitter.read()
            if not (ret_orig and ret_stab and ret_jitter):
                break
            h, w = frame_orig.shape[:2]
            frame_stab = cv2.resize(frame_stab, (w, h))
            frame_jitter = cv2.resize(frame_jitter, (w, h))
            if prev_frame_stab is not None:
                try:
                    flow_stab = self.calculate_optical_flow(prev_frame_stab, frame_stab)
                    motion_stab = np.mean(np.abs(flow_stab))
                    flow_jitter = self.calculate_optical_flow(prev_frame_jitter, frame_jitter)
                    motion_jitter = np.mean(np.abs(flow_jitter))
                    metrics['frame_stability'].append(float(motion_stab))
                    metrics['motion_reduction'].append(float(motion_jitter - motion_stab))
                except:
                    pass
            try:
                psnr = self.calculate_psnr(frame_orig, frame_stab)
                ssim = self.calculate_ssim(frame_orig, frame_stab)
                metrics['psnr_values'].append(float(psnr))
                metrics['ssim_values'].append(float(ssim))
            except:
                metrics['psnr_values'].append(20.0)
                metrics['ssim_values'].append(0.5)
            prev_frame_stab = frame_stab.copy()
            prev_frame_jitter = frame_jitter.copy()
            frame_count += 1
        cap_orig.release()
        cap_stab.release()
        cap_jitter.release()
        summary = {
            'mean_frame_stability': float(np.mean(metrics['frame_stability'])) if metrics['frame_stability'] else 0.0,
            'mean_motion_reduction': float(np.mean(metrics['motion_reduction'])) if metrics['motion_reduction'] else 0.0,
            'mean_psnr': float(np.mean(metrics['psnr_values'])) if metrics['psnr_values'] else 0.0,
            'mean_ssim': float(np.mean(metrics['ssim_values'])) if metrics['ssim_values'] else 0.0,
            'stability_improvement_ratio': 0.0
        }
        if metrics['frame_stability'] and metrics['motion_reduction']:
            avg_jitter_motion = summary['mean_frame_stability'] + summary['mean_motion_reduction']
            if avg_jitter_motion > 0:
                summary['stability_improvement_ratio'] = float(summary['mean_motion_reduction'] / avg_jitter_motion)
        return summary

    def convert_to_serializable(self, obj):
        if isinstance(obj, (np.float32, np.float64)):
            return float(obj)
        elif isinstance(obj, (np.int32, np.int64, np.int16, np.int8)):
            return int(obj)
        elif isinstance(obj, np.ndarray):
            return obj.tolist()
        elif isinstance(obj, dict):
            return {key: self.convert_to_serializable(value) for key, value in obj.items()}
        elif isinstance(obj, list):
            return [self.convert_to_serializable(item) for item in obj]
        elif isinstance(obj, tuple):
            return tuple(self.convert_to_serializable(item) for item in obj)
        else:
            return obj

    def compare_stabilization_methods(self, video_path, jitter_type="mixed", force_recreate_jitter=False):
        print(f"Comparing stabilization methods for: {video_path}")
        jittery_path = self.output_dir / "jittery_video.mp4"
        if force_recreate_jitter and jittery_path.exists():
            jittery_path.unlink()
        if not jittery_path.exists():
            self.add_artificial_jitter(video_path, jittery_path, jitter_type)
        else:
            print("Jittery video already exists, skipping creation...")
        results = {}
        for method_name, method_info in self.stabilizers.items():
            if not method_info['available']:
                print(f"Skipping {method_name} - not available. To enable: see error returned when attempting to run.")
                continue
            print(f"\nTesting {method_name}...")
            output_path = self.output_dir / f"stabilized_{method_name}.mp4"
            if output_path.exists():
                print(f"Output already exists for {method_name}, skipping processing...")
                stabilization_result = {'success': True, 'processing_time': 0, 'used_path': 'existing_file'}
            else:
                start_time = time.time()
                stabilization_result = method_info['function'](jittery_path, output_path)
            if stabilization_result.get('success'):
                metrics = self.calculate_stabilization_metrics(video_path, output_path, jittery_path)
                results[method_name] = {
                    'processing_time': float(stabilization_result.get('processing_time', 0)),
                    'metrics': metrics,
                    'output_path': str(output_path),
                    'success': True,
                    'used_path': stabilization_result.get('used_path', 'unknown')
                }
                print(f"✓ {method_name} completed (used_path={stabilization_result.get('used_path', 'unknown')})")
                if 'processing_time' in stabilization_result:
                    print(f"  Processing time: {stabilization_result['processing_time']:.2f}s")
                print(f"  Motion reduction: {metrics['mean_motion_reduction']:.3f}")
                print(f"  PSNR: {metrics['mean_psnr']:.2f} dB")
                print(f"  SSIM: {metrics['mean_ssim']:.3f}")
            else:
                results[method_name] = {
                    'success': False,
                    'error': stabilization_result.get('error', 'Unknown error'),
                    'used_path': stabilization_result.get('used_path', 'error')
                }
                print(f"✗ {method_name} failed: {stabilization_result.get('error', 'Unknown error')}")
        self.results = results
        self.generate_comparison_report()
        return results

    def generate_comparison_report(self):
        print("\nGenerating comparison report...")
        summary_data = []
        for method, result in self.results.items():
            if result.get('success'):
                summary_data.append({
                    'Method': method,
                    'Processing Time (s)': result['processing_time'],
                    'Motion Reduction': result['metrics']['mean_motion_reduction'],
                    'PSNR (dB)': result['metrics']['mean_psnr'],
                    'SSIM': result['metrics']['mean_ssim'],
                    'Stability Improvement Ratio': result['metrics']['stability_improvement_ratio'],
                    'Used Path': result.get('used_path', 'unknown')
                })
        serializable_results = self.convert_to_serializable(self.results)
        with open(self.output_dir / "stabilization_results.json", 'w') as f:
            json.dump(serializable_results, f, indent=2)
        self.plot_comparison_charts(summary_data)
        self.print_summary_table(summary_data)
        print(f"\nComplete results saved to: {self.output_dir}")

    def plot_comparison_charts(self, summary_data):
        if not summary_data:
            print("No data available for charts")
            return
        methods = [item['Method'] for item in summary_data]
        fig, axes = plt.subplots(2, 2, figsize=(15, 10))
        times = [item['Processing Time (s)'] for item in summary_data]
        axes[0, 0].bar(methods, times)
        axes[0, 0].set_title('Processing Time Comparison')
        axes[0, 0].set_ylabel('Time (seconds)')
        axes[0, 0].tick_params(axis='x', rotation=45)
        motion_reduction = [item['Motion Reduction'] for item in summary_data]
        axes[0, 1].bar(methods, motion_reduction)
        axes[0, 1].set_title('Motion Reduction Comparison')
        axes[0, 1].set_ylabel('Motion Reduction')
        axes[0, 1].tick_params(axis='x', rotation=45)
        psnr = [item['PSNR (dB)'] for item in summary_data]
        axes[1, 0].bar(methods, psnr)
        axes[1, 0].set_title('PSNR Comparison (Higher is Better)')
        axes[1, 0].set_ylabel('PSNR (dB)')
        axes[1, 0].tick_params(axis='x', rotation=45)
        ssim = [item['SSIM'] for item in summary_data]
        axes[1, 1].bar(methods, ssim)
        axes[1, 1].set_title('SSIM Comparison (Higher is Better)')
        axes[1, 1].set_ylabel('SSIM')
        axes[1, 1].tick_params(axis='x', rotation=45)
        plt.tight_layout()
        plt.savefig(self.output_dir / 'stabilization_comparison.png', dpi=300, bbox_inches='tight')
        plt.close()
        self.create_radar_chart(summary_data)

    def create_radar_chart(self, summary_data):
        if not summary_data:
            return
        methods = [item['Method'] for item in summary_data]
        metrics_to_plot = ['Processing Time (s)', 'Motion Reduction', 'PSNR (dB)', 'SSIM']
        normalized_data = []
        for metric in metrics_to_plot:
            values = [item[metric] for item in summary_data]
            if metric == 'Processing Time (s)':
                max_val = max(values) if max(values) > 0 else 1
                normalized = [1 - (v / max_val) for v in values]
            else:
                max_val = max(values) if max(values) > 0 else 1
                normalized = [v / max_val for v in values]
            normalized_data.append(normalized)
        angles = np.linspace(0, 2*np.pi, len(metrics_to_plot), endpoint=False).tolist()
        angles += angles[:1]
        fig, ax = plt.subplots(figsize=(10, 10), subplot_kw=dict(projection='polar'))
        colors = plt.cm.Set1(np.linspace(0, 1, len(methods)))
        for i, method in enumerate(methods):
            values = [data[i] for data in normalized_data]
            values += values[:1]
            ax.plot(angles, values, 'o-', linewidth=2, label=method, color=colors[i])
            ax.fill(angles, values, alpha=0.1, color=colors[i])
        ax.set_xticks(angles[:-1])
        ax.set_xticklabels(metrics_to_plot)
        ax.set_ylim(0, 1)
        ax.legend(loc='upper right', bbox_to_anchor=(1.3, 1.0))
        plt.title('Stabilization Method Comparison (Normalized)', size=14, y=1.08)
        plt.tight_layout()
        plt.savefig(self.output_dir / 'stabilization_radar_chart.png', dpi=300, bbox_inches='tight')
        plt.close()

    def print_summary_table(self, summary_data):
        if not summary_data:
            print("No successful stabilization results to display")
            return
        print("\n" + "="*80)
        print("STABILIZATION METHOD COMPARISON SUMMARY")
        print("="*80)
        headers = ["Method", "Time (s)", "Motion Reduction", "PSNR (dB)", "SSIM", "Improvement Ratio", "Used Path"]
        rows = []
        for item in summary_data:
            rows.append([
                item['Method'],
                f"{item['Processing Time (s)']:.2f}",
                f"{item['Motion Reduction']:.3f}",
                f"{item['PSNR (dB)']:.2f}",
                f"{item['SSIM']:.3f}",
                f"{item['Stability Improvement Ratio']:.3f}" if item['Stability Improvement Ratio'] else "N/A",
                item.get('Used Path', 'unknown')
            ])
        col_widths = [max(len(str(row[i])) for row in rows + [headers]) for i in range(len(headers))]
        header_line = " | ".join(f"{headers[i]:<{col_widths[i]}}" for i in range(len(headers)))
        print(header_line)
        print("-" * len(header_line))
        for row in rows:
            row_line = " | ".join(f"{row[i]:<{col_widths[i]}}" for i in range(len(row)))
            print(row_line)

